  actual: exit 0
  status: pass
- requirement: script.py is executable
  command: test -x script.py
  expected: exit 0
  actual: exit 1
  status: fixed
''';

    test('parses the unfenced heading + bullet shape', () {
      final ledger = parseTaskLedger('Answer text.\n$unfencedLedger\nDone.');
      expect(ledger, isNotNull);
