  // entries were mid-run strips — stashed for the transcript, never for
  // the gate.
  _StrippedLedger? fold;
  for (final entry in stash) {
    if (identical(entry.original, terminal)) fold = entry;
  }
  if (fold == null) return;
  final matched = fold;
