      final events = await runTurns([
        textTurn(ledgerText),
      ], finalizeGate: false);
      expect(events.whereType<TaskLedgerEvent>(), isEmpty);
    },
  );

  test(
    'finalizeGate on + no ledger in the answer: no event (degrades clean)',
    () async {
      final events = await runTurns([
        textTurn('plain answer, no ledger'),
      ], finalizeGate: true);
      expect(events.whereType<TaskLedgerEvent>(), isEmpty);
