```dart
/// Ends the run when the assistant [message] failed or was aborted, emitting
/// the closing `turn_end`/`agent_end` and returning the run's messages.
/// Returns `null` for a healthy message so the turn continues.
///
/// The FinalizeGate fold runs here too (gh-1516 review): the
/// `MessageEndEvent` interceptor already stripped and persisted the
/// ledger-free answer DURING the run, so without the fold an
/// error/aborted run would lose the hidden `task_ledger` record (and ship
/// the unstripped original in `AgentEndEvent`). An aborted run still ends
/// on an assistant answer, so gh-1412's "run must end on the answer" rule
/// is satisfied.
Future<List<Message>?> _terminalRunMessages(
  AssistantMessage message,
  List<Message> newMessages,
  List<Message> contextMessages,
  List<_StrippedLedger> stash,
  bool finalizeGate,
  AgentEventSink emit,
) async {
  if (message.stopReason != StopReason.error &&
      message.stopReason != StopReason.aborted) {
    return null;
  }
  if (finalizeGate) {
    await _emitFinalizeGateFold(newMessages, contextMessages, stash, emit);
  }
  await emit(TurnEndEvent(message: message, toolResults: const []));
  await emit(AgentEndEvent(List.unmodifiable(newMessages)));
  return newMessages;
}
```

